-- One authoritative academic record. Only server-verified admin routes can write.
create table if not exists public.academic_record (
  id text primary key check (id = 'marley'),
  courses jsonb not null check (jsonb_typeof(courses) = 'array'),
  revision bigint not null default 0 check (revision >= 0),
  updated_at timestamptz not null default now()
);
alter table public.academic_record enable row level security;
revoke all on public.academic_record from anon, authenticated;
grant select, insert, update on public.academic_record to service_role;

